-- Demo mode (#93): organization.is_demo flags a fictional sample workspace (default false); workspace_settings.demo_version records the seed version it was restored to. app_demo_workspaces() is the one cross-workspace read of the demo workspaces (a visitor has no workspace yet; the nightly reset has none either): ids and slugs only. Additive only.
ALTER TABLE "organization" ADD COLUMN "is_demo" boolean DEFAULT false NOT NULL;--> statement-breakpoint
ALTER TABLE "workspace_settings" ADD COLUMN "demo_version" text;--> statement-breakpoint
CREATE FUNCTION app_demo_workspaces()
  RETURNS TABLE (workspace_id uuid, slug text)
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp
  AS $$
    SELECT o.id, o.slug::text
    FROM organization o
    WHERE o.is_demo AND o.deleted_at IS NULL
    ORDER BY o.slug
  $$;--> statement-breakpoint
REVOKE ALL ON FUNCTION app_demo_workspaces() FROM PUBLIC;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app_demo_workspaces() TO causedeck_app;
